from slugify import slugify


def test_spaces_become_hyphens():
    assert slugify("Hello World") == "hello-world"


def test_punctuation_and_extra_spaces():
    assert slugify("  Hello,   World!! ") == "hello-world"


def test_accents_are_removed():
    assert slugify("Crème brûlée à la carte") == "creme-brulee-a-la-carte"


def test_digits_are_kept():
    assert slugify("Top 10 tips for 2026") == "top-10-tips-for-2026"


def test_nothing_left():
    assert slugify("!!! ???") == ""


def test_cut_at_a_hyphen():
    assert slugify("one two three four", max_length=9) == "one-two"


def test_single_long_word_is_cut():
    assert slugify("a" * 20, max_length=5) == "aaaaa"

