"""Monthly totals by category from a bank CSV export. An AI assistant wrote this in one go: it handles the
happy path, but not the real export. Run: python budget.py transactions.csv"""

import csv
import sys
from collections import defaultdict
from datetime import datetime


def parse_amount(text):
    return float(text)


def parse_date(text):
    return datetime.strptime(text, "%Y-%m-%d").date()


def summarise(path):
    """Return ({(month, category): total}, [problems]) where month is 'YYYY-MM'."""
    totals = defaultdict(float)
    problems = []
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            month = parse_date(row["date"]).strftime("%Y-%m")
            totals[month, row["category"]] += parse_amount(row["amount"])
    return dict(totals), problems


def main():
    totals, problems = summarise(sys.argv[1])
    for (month, category), total in sorted(totals.items()):
        print(f"{month}  {category:<14}{total:>10.2f}")
    for p in problems:
        print("skipped:", p)


if __name__ == "__main__":
    main()

import pytest

from budget import parse_amount, parse_date, summarise


def test_plain_amount():
    assert parse_amount("54.20") == 54.20


def test_amount_with_currency_and_thousands():
    assert parse_amount("£1,200.00") == 1200.00


def test_negative_amount():
    assert parse_amount("-30.00") == -30.00


def test_iso_date():
    assert parse_date("2026-03-02").isoformat() == "2026-03-02"


def test_day_first_date():
    assert parse_date("05/03/2026").isoformat() == "2026-03-05"


def test_bad_amount_raises_value_error():
    with pytest.raises(ValueError):
        parse_amount("not-a-number")


@pytest.fixture
def result():
    return summarise("transactions.csv")


def test_categories_ignore_case(result):
    totals, _ = result
    assert totals["2026-03", "Transport"] == pytest.approx(0.0)
    assert totals["2026-04", "Food"] == pytest.approx(61.75)


def test_missing_category_is_uncategorised(result):
    totals, _ = result
    assert totals["2026-04", "Uncategorised"] == pytest.approx(3.20)


def test_rent_and_cinema_are_counted(result):
    totals, _ = result
    assert totals["2026-03", "Housing"] == pytest.approx(1200.00)
    assert totals["2026-03", "Fun"] == pytest.approx(12.50)


def test_bad_and_blank_rows_are_reported_not_fatal(result):
    _, problems = result
    assert len(problems) == 1 and "Broken row" in problems[0]

"""The contract for the habit tracker API, slice by slice. Run: pytest -q"""
from fastapi.testclient import TestClient

from app import app, reset

client = TestClient(app)


def setup_function():
    reset()


def test_slice_1_create_and_list_habits():
    r = client.post("/habits", json={"name": "Read 20 pages"})
    assert r.status_code == 201
    assert r.json() == {"id": 1, "name": "Read 20 pages", "check_ins": []}
    assert client.get("/habits").json() == [{"id": 1, "name": "Read 20 pages", "check_ins": []}]


def test_slice_1_name_is_required_and_trimmed():
    assert client.post("/habits", json={"name": "   "}).status_code == 422
    assert client.post("/habits", json={"name": "  Walk  "}).json()["name"] == "Walk"


def test_slice_2_check_in_on_a_day():
    client.post("/habits", json={"name": "Walk"})
    r = client.post("/habits/1/check-ins", json={"day": "2026-10-01"})
    assert r.status_code == 201
    assert client.get("/habits/1").json()["check_ins"] == ["2026-10-01"]


def test_slice_2_checking_in_twice_on_one_day_counts_once():
    client.post("/habits", json={"name": "Walk"})
    client.post("/habits/1/check-ins", json={"day": "2026-10-01"})
    assert client.post("/habits/1/check-ins", json={"day": "2026-10-01"}).status_code == 200
    assert client.get("/habits/1").json()["check_ins"] == ["2026-10-01"]


def test_slice_2_unknown_habit_is_404():
    assert client.post("/habits/99/check-ins", json={"day": "2026-10-01"}).status_code == 404
    assert client.get("/habits/99").status_code == 404


def test_slice_3_streak_counts_consecutive_days():
    client.post("/habits", json={"name": "Walk"})
    for day in ("2026-10-01", "2026-10-02", "2026-10-03", "2026-10-05", "2026-10-06"):
        client.post("/habits/1/check-ins", json={"day": day})
    r = client.get("/habits/1/streak", params={"today": "2026-10-06"})
    assert r.json() == {"current": 2, "longest": 3}


def test_slice_3_streak_is_zero_after_a_missed_day():
    client.post("/habits", json={"name": "Walk"})
    client.post("/habits/1/check-ins", json={"day": "2026-10-01"})
    assert client.get("/habits/1/streak", params={"today": "2026-10-03"}).json() == {"current": 0, "longest": 1}


def test_slice_3_bad_date_is_422():
    client.post("/habits", json={"name": "Walk"})
    assert client.post("/habits/1/check-ins", json={"day": "1st October"}).status_code == 422
